// Homepage pig: adaptive rendering with full-resolution Blender geometry at the top tier.
// The local bundle is generated by npm run build:three.
import {
    Scene, Group, Box3, Vector3, PerspectiveCamera, WebGLRenderer,
    DirectionalLight, EquirectangularReflectionMapping,
    SRGBColorSpace, AgXToneMapping, GLTFLoader, EXRLoader,
} from './vendor/three-pig.js';
import { END_ANIMATION_DURATION } from './boids/config.js';
import { heroField } from './boids/hero-field.js';
import { PigQuality, PIG_QUALITY } from './pig-quality.js';

function modelURL(name) {
    const suffix = name === 'full' ? '' : `-${name}`;
    return new URL(`../models/slypork-pig${suffix}.glb`, import.meta.url).href;
}
const ENVIRONMENT_URL = new URL('../models/forest.exr', import.meta.url).href;
const REST_YAW = -0.4;
const REST_PITCH = 0.08;
const MAX_WIDTH = 900;
const SPIN_TURN_DURATION = 0.5;
const SPIN_SETTLE_DURATION = 0.19;
const SPIN_DURATION = SPIN_TURN_DURATION + SPIN_SETTLE_DURATION;
const SECRET_GLANCES = [0.18, 0.32, 0.46, 0.6];
const SECRET_PITCH = 0.48;
const POINTER_PITCH_RANGE = 0.1;
// The bottom-edge cursor pose is the shallowest second-click egg glance.
const NAV_PITCH_LIMIT = REST_PITCH - POINTER_PITCH_RANGE
    + (SECRET_PITCH - REST_PITCH + POINTER_PITCH_RANGE) * SECRET_GLANCES[2];
const SECRET_NOD_DURATION = 0.65;
const BURST_NOD_LEAD = 0.16;
const BURST_WINDUP_DURATION = 1.05;
const BURST_SETTLE_DURATION = 0.85;
// About four minutes per gentle seesaw, versus twenty seconds per figure-eight.
const RING_SWAY_SPEED = 0.025;

function setupNavigation(stage) {
    const nav = document.getElementById('site-nav');
    function setOpen(open) {
        if (!open && nav.contains(document.activeElement)) stage.focus();
        nav.inert = !open;
        nav.setAttribute('aria-hidden', String(!open));
        nav.classList.toggle('is-open', open);
        stage.setAttribute('aria-expanded', String(open));
        stage.setAttribute('aria-label', open ? 'Hide navigation' : 'Show navigation');
        document.body.dispatchEvent(new CustomEvent('layoutChanged'));
    }
    setOpen(false);
    stage.addEventListener('click', () => {
        setOpen(stage.getAttribute('aria-expanded') !== 'true');
    });
    let wasOpen = false;
    let flockSession = false;
    document.body.addEventListener('simulationStarted', () => {
        wasOpen = nav.classList.contains('is-open');
        flockSession = true;
        setOpen(true);
    });
    document.body.addEventListener('simulationStopped', () => {
        if (!flockSession) return;
        flockSession = false;
        // The renderer re-enables the button in its own stop listener first,
        // allowing focus to return there if a navigation link was focused.
        queueMicrotask(() => setOpen(wasOpen));
    });
    document.addEventListener('keydown', event => {
        if (!stage.disabled && event.key === 'Escape' && nav.classList.contains('is-open')) {
            setOpen(false);
        }
    });
    // Keep the routes reachable if the browser cannot render the 3D button.
    return () => setOpen(true);
}

async function mountPig(stage) {
    const canvas = stage.querySelector('canvas');
    const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
    const quality = new PigQuality({ coarsePointer: matchMedia('(pointer: coarse)').matches });
    const initialModel = PIG_QUALITY[quality.level].model;
    const renderer = new WebGLRenderer({ canvas, alpha: true, antialias: true });
    renderer.setClearColor(0x000000, 0);
    renderer.outputColorSpace = SRGBColorSpace;
    renderer.toneMapping = AgXToneMapping;
    renderer.toneMappingExposure = 1.15;

    const scene = new Scene();
    const camera = new PerspectiveCamera(28, 1, 0.1, 30);
    const pivot = new Group();
    scene.add(pivot);
    const key = new DirectionalLight(0xfffaf4, 2.5);
    key.position.set(-3, 4, 5);
    const fill = new DirectionalLight(0xe3edff, 0.65);
    fill.position.set(4, 1, 3);
    const redRim = new DirectionalLight(0xff5577, 2.6);
    const blueRim = new DirectionalLight(0x5599ff, 3.0);
    scene.add(key, fill, redRim, blueRim);

    const glow = new Map();
    const appliedGlow = new Map();
    let lastGlowTime = -Infinity;
    function paintGlow() {
        const now = performance.now();
        // Blurred gradients are costly to repaint. Keep lighting at full frame
        // rate but update the soft backdrop at 15 Hz on the lower quality tiers.
        if (quality.level > 0 && now - lastGlowTime < 1000 / 15) return;
        lastGlowTime = now;
        for (const [name, value] of glow) {
            if (appliedGlow.get(name) === value) continue;
            stage.style.setProperty(name, value);
            appliedGlow.set(name, value);
        }
    }

    // The coloured lights orbit behind the head relative to the cursor's key
    // light, with a small idle drift, as in the original homepage animation.
    function positionRims(time = 0) {
        const angle = Math.atan2(key.position.y, key.position.x);
        const drift = reducedMotion.matches ? 0 : 0.35 * Math.sin(time * 0.21);
        const restAngle = Math.atan2(4, -3);
        const place = (light, offset, lift, colour, originX, originY) => {
            const a = angle + offset + drift;
            light.position.set(Math.cos(a) * 3, (Math.sin(a) + lift) * 3, -2.2);
            // Gently shift the ambient glow with its rim light, relative to
            // the authored resting centre. CSS's vertical axis points down.
            const glowX = originX + (Math.cos(a) - Math.cos(restAngle + offset)) * 4.5;
            const glowY = originY - (Math.sin(a) - Math.sin(restAngle + offset)) * 3.6;
            glow.set(`--hero-${colour}-x`, `${glowX.toFixed(2)}%`);
            glow.set(`--hero-${colour}-y`, `${glowY.toFixed(2)}%`);
        };
        place(redRim, Math.PI, 0.2, 'warm', 35, 55);
        place(blueRim, Math.PI * 0.45, -0.1, 'cool', 68, 42);
    }
    positionRims();

    let model;
    let centre;
    try {
        const [gltf, panorama] = await Promise.all([
            new GLTFLoader().loadAsync(modelURL(initialModel)),
            new EXRLoader().loadAsync(ENVIRONMENT_URL),
        ]);
        model = gltf.scene;
        // Keep all separate meshes, authored normals, and double-sided materials.
        // No recalculated normals, geometry simplification, or custom shaders.
        const bounds = new Box3().setFromObject(model);
        centre = bounds.getCenter(new Vector3());
        model.position.sub(centre);
        pivot.add(model);
        panorama.mapping = EquirectangularReflectionMapping;
        // Three.js prefilters the HDR map for PBR automatically. Retaining the
        // source also lets it rebuild the reflections after WebGL context loss.
        scene.environment = panorama;
        scene.environmentIntensity = 0.8;
        // Place the canopy and its gaps in the reflected view of both lenses.
        scene.environmentRotation.set(0.35, 1.2, 0);
    } catch (error) {
        renderer.dispose();
        throw error;
    }

    // Meshes are rigid: only the pivot animates. Avoid rebuilding local matrices
    // for every mesh on every frame, while retaining world-matrix propagation.
    function freezeModel(root) {
        root.traverse(object => { object.updateMatrix(); object.matrixAutoUpdate = false; });
    }
    freezeModel(model);
    const models = new Map([[initialModel, model]]);
    const pendingModels = new Set();
    function selectModel() {
        const name = PIG_QUALITY[quality.level].model;
        const ready = models.get(name);
        if (ready) {
            for (const [key, root] of models) root.visible = key === name;
        } else if (!pendingModels.has(name)) {
            pendingModels.add(name);
            // Simplification happens offline, never on the animation thread.
            new GLTFLoader().loadAsync(modelURL(name))
                .then(gltf => {
                    const root = gltf.scene;
                    root.position.sub(centre);
                    freezeModel(root);
                    root.visible = false;
                    pivot.add(root);
                    models.set(name, root);
                    selectModel();
                    quality.reset();
                    if (reducedMotion.matches) sync();
                })
                .catch(error => console.warn('Pig detail level unavailable; retaining loaded geometry.', error));
        }
    }

    let width = 0;
    let height = 0;
    let frame = 0;
    let lastTime = 0;
    let elapsed = 0;
    let inView = true;
    let flockActive = document.body.classList.contains('boid-active');
    let contextLost = false;
    let renderWidth = 0;
    let renderHeight = 0;
    let renderRatio = 0;
    let renderLeft = 0;
    let renderTop = 0;
    let entrancePending = false;
    const flight = {
        amount: 0, from: 0, to: 0, elapsed: 0, duration: 1.8, phase: 0,
        ringPhase: 0, ringTilt: heroField.ringAngle,
    };
    const projected = new Vector3();
    const projectedEdge = new Vector3();
    const pointer = { x: 0, y: 0, active: false, movedAt: 0 };
    const nav = document.getElementById('site-nav');
    const navLinks = document.getElementById('navLinks');
    const egg = document.getElementById('easterEgg');
    const attention = {
        link: null, pressedLink: null, selectedLink: null, focusedLink: null,
        egg: false, x: 0, y: 0, mix: 0, secret: 0,
        glance: 0, yaw: REST_YAW, pitch: REST_PITCH,
    };
    const discovery = { count: 0, nodElapsed: SECRET_NOD_DURATION };
    const burst = { phase: null, elapsed: 0, pitch: 0, yaw: 0, roll: 0, x: 0, y: 0, from: null, to: null };
    const tumbleAxes = [new Vector3(1, 0, 0), new Vector3(0, 1, 0), new Vector3(0, 0, 1)];
    const hop = { target: null, lift: 0, from: 0, height: 0, elapsed: 0.45, duration: 0.45 };

    function attentionTarget() {
        if (!nav.classList.contains('is-open')) return null;
        const focused = attention.focusedLink?.matches(':focus-visible') ? attention.focusedLink : null;
        return attention.selectedLink || attention.pressedLink || attention.link || focused;
    }
    let hovered = false;
    const spin = { angle: 0, from: 0, to: 0, elapsed: SPIN_DURATION, velocity: 0, landing: null };
    const pose = { yaw: REST_YAW, pitch: REST_PITCH, roll: 0, scale: 1 };
    const baseBounds = new Box3().setFromObject(pivot);
    const size = baseBounds.getSize(new Vector3());
    // A little extra space accommodates the shy tilt without cropping the ears.
    const halfWidth = size.x * 0.59;
    const halfHeight = size.y * 0.61;
    const halfDepth = size.z * 0.5;
    const boundCorners = [];
    for (const x of [baseBounds.min.x, baseBounds.max.x]) {
        for (const y of [baseBounds.min.y, baseBounds.max.y]) {
            for (const z of [baseBounds.min.z, baseBounds.max.z]) boundCorners.push(new Vector3(x, y, z));
        }
    }
    const boundPoint = new Vector3();

    function frameCanvas(rect, scale) {
        // Project the eight corners of the original bounds, not every vertex.
        // Retain the full size through transitions to avoid reallocating the
        // drawing buffer on each animation frame as the pig shrinks or grows.
        const framingScale = flight.amount === 1 && flight.to === 1 ? scale : 1.04;
        const focal = height / (2 * Math.tan(camera.fov * Math.PI / 360));
        const distance = camera.position.z;
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
        for (const corner of boundCorners) {
            boundPoint.copy(corner).multiplyScalar(framingScale).applyQuaternion(pivot.quaternion).add(pivot.position);
            const perspective = focal / Math.max(camera.near, distance - boundPoint.z);
            const x = rect.left + width / 2 + boundPoint.x * perspective;
            const y = rect.top + height / 2 - boundPoint.y * perspective;
            minX = Math.min(minX, x); maxX = Math.max(maxX, x);
            minY = Math.min(minY, y); maxY = Math.max(maxY, y);
        }
        let w = Math.min(innerWidth, Math.ceil((maxX - minX + 8) / 64) * 64);
        let h = Math.min(innerHeight, Math.ceil((maxY - minY + 8) / 64) * 64);
        // Grow immediately; leave slack before shrinking so gentle orbiting
        // cannot repeatedly reallocate at a size boundary.
        if (w < renderWidth && w > renderWidth - 128) w = Math.min(innerWidth, renderWidth);
        if (h < renderHeight && h > renderHeight - 128) h = Math.min(innerHeight, renderHeight);
        const ratio = Math.min(devicePixelRatio || 1, PIG_QUALITY[quality.level].pixelRatio);
        if (w !== renderWidth || h !== renderHeight || ratio !== renderRatio) {
            renderer.setDrawingBufferSize(w, h, ratio);
            canvas.style.width = `${w}px`;
            canvas.style.height = `${h}px`;
            renderWidth = w;
            renderHeight = h;
            renderRatio = ratio;
        }
        const x = (minX + maxX) / 2;
        const y = (minY + maxY) / 2;
        const left = Math.round(Math.max(0, Math.min(innerWidth - w, x - w / 2)));
        const top = Math.round(Math.max(0, Math.min(innerHeight - h, y - h / 2)));
        if (left !== renderLeft || top !== renderTop) {
            canvas.style.transform = `translate(${left}px, ${top}px)`;
            renderLeft = left;
            renderTop = top;
        }
        const view = camera.view;
        if (!view || view.fullWidth !== width || view.fullHeight !== height
            || view.offsetX !== left - rect.left || view.offsetY !== top - rect.top
            || view.width !== w || view.height !== h) {
            camera.setViewOffset(width, height, left - rect.left, top - rect.top, w, h);
        }
    }

    function canRender() {
        return !contextLost && !document.hidden && inView && width > 0 && height > 0;
    }

    function draw(dt = 0) {
        if (!canRender()) return;
        const amount = flight.amount;
        const orbit = flight.phase;
        const viewHeight = 2 * camera.position.z * Math.tan(camera.fov * Math.PI / 360);
        const viewWidth = viewHeight * camera.aspect;
        const rect = stage.getBoundingClientRect();
        // The idle figure-eight is anchored to the original stage.
        pivot.position.set(
            Math.sin(orbit) * viewWidth * 0.27 * amount,
            (Math.cos(orbit * 2) * 0.12 + 0.055) * viewHeight * amount,
            0,
        );
        if (!reducedMotion.matches) pivot.position.y += Math.sin(elapsed * 1.1) * 0.015 * (1 - amount);
        const fullWidth = size.x / viewWidth * width;
        const miniature = Math.max(0.2, Math.min(0.4, 76 / fullWidth));
        const scale = (1 - amount * (1 - miniature)) * pose.scale;
        pivot.scale.setScalar(scale);

        const link = attentionTarget();
        const target = flockActive ? link : null;
        const follow = reducedMotion.matches ? 1 : 1 - Math.exp(-dt * 12);
        // Aim at the link while the independent full turn is still running,
        // so the turn lands in the glance instead of returning to the idle pose.
        const glanceTarget = link && !flockActive && !burst.phase ? 1 : 0;
        attention.glance += (glanceTarget - attention.glance) * follow;
        if (link && !flockActive) {
            const linkRect = link.getBoundingClientRect();
            const linksRect = navLinks.getBoundingClientRect();
            const dx = linkRect.left + linkRect.width / 2 - (rect.left + width / 2);
            const dy = Math.max(1, linkRect.top + linkRect.height / 2 - (rect.top + height / 2));
            // Spread the turns across the row without flattening its outer links.
            const yaw = dx / Math.max(1, linksRect.width / 2) * 0.7;
            const bottom = Math.max(1, linksRect.bottom - linkRect.height / 2 - (rect.top + height / 2));
            const pitch = NAV_PITCH_LIMIT * Math.min(1, dy / bottom);
            attention.yaw += (yaw - attention.yaw) * follow;
            attention.pitch += (pitch - attention.pitch) * follow;
        }
        let targetX = 0;
        let targetY = 0;
        if (target) {
            const targetRect = target.getBoundingClientRect();
            const radius = fullWidth * miniature / 2;
            // Perspective exposes more of the ears at the far viewport edge.
            const margin = radius * 1.35 + 16;
            const x = Math.max(margin, Math.min(innerWidth - margin,
                targetRect.left + targetRect.width / 2));
            // Stay above both rows on mobile, keeping every route unobscured.
            const top = Math.min(targetRect.top, nav.getBoundingClientRect().top);
            const y = Math.max(radius + 12, Math.min(innerHeight - radius - 12, top - radius - 18));
            targetX = (x - rect.left - width / 2) / width * viewWidth - pivot.position.x;
            targetY = -(y - rect.top - height / 2) / height * viewHeight - pivot.position.y;
        }
        if (target !== hop.target) {
            const betweenLinks = target && hop.target && nav.contains(target) && nav.contains(hop.target);
            // Retarget from the current lift so quick reversals stay continuous.
            hop.from = hop.lift;
            const lift = betweenLinks ? Math.min(36, Math.abs(targetX - attention.x) / viewWidth * width * 0.16) : 0;
            hop.height = Math.max(0, lift - hop.from);
            hop.elapsed = 0;
            hop.target = target;
        }
        hop.elapsed = reducedMotion.matches ? hop.duration : Math.min(hop.duration, hop.elapsed + dt);
        const hopProgress = hop.elapsed / hop.duration;
        const hopEase = hopProgress * hopProgress * (3 - 2 * hopProgress);
        hop.lift = reducedMotion.matches || hopProgress === 1 ? 0
            : hop.from * (1 - hopEase) + Math.sin(Math.PI * hopProgress) * hop.height;
        attention.x += (targetX - attention.x) * follow;
        attention.y += (targetY - attention.y) * follow;
        attention.mix += ((target ? 1 : 0) - attention.mix) * follow;
        // Accepted taps hold the glance even after a touch or pointer leaves.
        const secretTarget = !flockActive && (attention.egg || discovery.count)
            ? SECRET_GLANCES[discovery.count] : 0;
        attention.secret += (secretTarget - attention.secret) * follow;
        pivot.position.x += attention.x * amount;
        pivot.position.y += (attention.y + hop.lift / height * viewHeight) * amount;
        pivot.position.x += burst.x * viewWidth;
        pivot.position.y += burst.y * viewHeight;
        const inspect = attention.mix * amount;
        // Keep the bowed pig gently afloat, blending the bob with link attention.
        if (!reducedMotion.matches) {
            pivot.position.y += Math.sin(elapsed * Math.PI * 2 / 4) * 4 / height * viewHeight * inspect;
        }
        const secret = attention.secret * (1 - amount);
        let pitch = pose.pitch + Math.sin(orbit * 2) * 0.15 * amount;
        let yaw = pose.yaw + Math.cos(orbit) * 0.5 * amount;
        let roll = pose.roll - Math.cos(orbit) * 0.23 * amount;
        // A deliberate bow over the link; the snout points down the page.
        pitch += (1.05 - pitch) * inspect;
        yaw *= 1 - inspect;
        roll *= 1 - inspect;
        // Before discovery, the big pig gives away the hiding place with a
        // glance toward the corner and a small, conspiratorial head tilt.
        pitch += (SECRET_PITCH - pitch) * secret;
        yaw += (0.65 - yaw) * secret;
        roll += (-0.08 - roll) * secret;
        // The third nod is continued by the tumble's pitch below.
        if (!reducedMotion.matches && !flockActive && discovery.count < 3) {
            const nodProgress = discovery.nodElapsed / SECRET_NOD_DURATION;
            pitch += Math.sin(Math.PI * nodProgress) ** 2 * (0.025 + discovery.count * 0.015);
        }
        // The full-size pig watches the link from its place in the hero.
        const glance = attention.glance * (1 - amount);
        pitch += (attention.pitch - pitch) * glance;
        yaw += (attention.yaw - yaw) * glance;
        roll *= 1 - glance;
        if (link && !flockActive && !burst.phase) pitch = Math.min(pitch, NAV_PITCH_LIMIT);
        // Keep whole turns outside the glance blend so hover cannot shorten a spin.
        pivot.rotation.set(pitch, yaw + spin.angle, roll);
        // Spin around the screen's axes, rather than coupling three Euler
        // angles that can cancel the turn and keep the snout facing one side.
        pivot.rotateOnWorldAxis(tumbleAxes[0], burst.pitch);
        pivot.rotateOnWorldAxis(tumbleAxes[1], burst.yaw);
        pivot.rotateOnWorldAxis(tumbleAxes[2], burst.roll);
        frameCanvas(rect, scale);
        renderer.render(scene, camera);
        projected.copy(pivot.position).project(camera);
        projectedEdge.copy(pivot.position);
        projectedEdge.x += size.x * scale * 0.5;
        projectedEdge.project(camera);
        heroField.x = renderLeft + (projected.x + 1) * renderWidth / 2;
        heroField.y = renderTop + (1 - projected.y) * renderHeight / 2;
        heroField.radius = Math.abs(projectedEdge.x - projected.x) * renderWidth / 2;
        heroField.strength = amount;
        // Rock through horizontal, using the original tilt as either limit.
        heroField.ringAngle = flight.ringTilt * Math.cos(flight.ringPhase);
        heroField.anchor = target;
        const remainingTravel = Math.hypot((targetX - attention.x) / viewWidth * width,
            (targetY - attention.y) / viewHeight * height);
        heroField.travelling = remainingTravel > 10 || hopProgress < 1;
        heroField.available = heroField.x >= 0 && heroField.x <= innerWidth
            && heroField.y >= 0 && heroField.y <= innerHeight;
        glow.set('--flock-glow', String(1 - amount));
        // All layout reads are complete before changing the backdrop's styles.
        paintGlow();
        // Wait until pixels are ready; two animation frames give the browser
        // an opportunity to paint opacity 0 before starting the entrance fade.
        if (!entrancePending && !stage.classList.contains('pig-ready')) {
            entrancePending = true;
            requestAnimationFrame(() => requestAnimationFrame(() => {
                entrancePending = false;
                if (!contextLost) {
                    stage.classList.add('pig-ready');
                    stage.disabled = flockActive;
                }
            }));
        }
    }

    function tick(time) {
        frame = 0;
        if (!canRender() || reducedMotion.matches) return;
        if (quality.sample(time)) selectModel();
        const dt = lastTime ? Math.min((time - lastTime) / 1000, 0.05) : 0;
        lastTime = time;
        elapsed += dt;
        discovery.nodElapsed = Math.min(SECRET_NOD_DURATION, discovery.nodElapsed + dt);
        updateBurst(dt);
        if (flight.elapsed < flight.duration) {
            flight.elapsed = Math.min(flight.duration, flight.elapsed + dt);
            const t = flight.elapsed / flight.duration;
            const eased = t * t * (3 - 2 * t);
            flight.amount = flight.from + (flight.to - flight.from) * eased;
        }
        if (flockActive && !attentionTarget()) flight.phase += dt * 0.32;
        // Keep the ring swaying even while the pig pauses to inspect a link.
        if (flockActive) flight.ringPhase = (flight.ringPhase + dt * RING_SWAY_SPEED) % (Math.PI * 2);
        if (spin.elapsed < SPIN_DURATION) {
            // Retarget the unfinished revolution from its current angle and
            // speed. The link landing has no overshoot or backwards correction.
            if (!spin.landing && attentionTarget() && spin.angle < spin.to) {
                const duration = SPIN_DURATION - spin.elapsed;
                spin.landing = {
                    from: spin.angle, startedAt: spin.elapsed, duration,
                    tangent: Math.min(Math.max(0, spin.velocity * duration), 3 * (spin.to - spin.angle)),
                };
            }
            const previousAngle = spin.angle;
            spin.elapsed = Math.min(SPIN_DURATION, spin.elapsed + dt);
            const progress = spin.elapsed / SPIN_DURATION;
            if (spin.landing) {
                const { from, startedAt, duration, tangent } = spin.landing;
                const t = Math.min(1, (spin.elapsed - startedAt) / duration);
                const ease = t * t * (3 - 2 * t);
                spin.angle = from + (spin.to - from) * ease + tangent * t * (1 - t) ** 2;
            } else {
                // Keep the 14-degree overshoot, then ease into a slower return
                // from zero speed so the reversal carries the head's weight.
                const turning = spin.elapsed < SPIN_TURN_DURATION;
                const phase = turning ? spin.elapsed / SPIN_TURN_DURATION
                    : (spin.elapsed - SPIN_TURN_DURATION) / SPIN_SETTLE_DURATION;
                const eased = turning
                    ? 1.04 * (phase < 0.5 ? 4 * phase ** 3 : 1 - (-2 * phase + 2) ** 3 / 2)
                    : 1 + 0.04 * (1 - phase * phase * (3 - 2 * phase));
                spin.angle = spin.from + (spin.to - spin.from) * eased;
            }
            if (dt) spin.velocity = (spin.angle - previousAngle) / dt;
            if (progress === 1) resetSpin();
        }
        let yaw = REST_YAW + 0.055 * Math.sin(elapsed * 0.4);
        let pitch = REST_PITCH + 0.025 * Math.sin(elapsed * 0.53);
        let roll = 0;
        let lightX = -3;
        let lightY = 4;
        if (pointer.active) {
            const rect = stage.getBoundingClientRect();
            const x = Math.max(-1, Math.min(1, (pointer.x - rect.left - width / 2) / (width / 2)));
            const y = Math.max(-1, Math.min(1, (pointer.y - rect.top - height / 2) / (height / 2)));
            const peek = time - pointer.movedAt > 1800 ? 0.35 : 1;
            yaw = REST_YAW - x * 0.22 * peek;
            pitch = REST_PITCH - y * POINTER_PITCH_RANGE * peek;
            roll = -x * 0.025 * peek;
            lightX = x * 3;
            lightY = 2 - y * 2;
        }
        const follow = 1 - Math.exp(-dt * 4);
        pose.yaw += (yaw - pose.yaw) * follow;
        pose.pitch += (pitch - pose.pitch) * follow;
        pose.roll += (roll - pose.roll) * follow;
        pose.scale += ((hovered && !flockActive ? 1.035 : 1) - pose.scale) * follow;
        key.position.x += (lightX - key.position.x) * follow;
        key.position.y += (lightY - key.position.y) * follow;
        positionRims(elapsed);
        draw(dt);
        frame = requestAnimationFrame(tick);
    }

    function sync() {
        cancelAnimationFrame(frame);
        frame = 0;
        lastTime = 0;
        quality.reset();
        if (reducedMotion.matches) {
            resetSpin();
            discovery.nodElapsed = SECRET_NOD_DURATION;
            resetBurst();
            Object.assign(pose, { yaw: REST_YAW, pitch: REST_PITCH, roll: 0, scale: 1 });
            flight.amount = flight.to;
            flight.elapsed = flight.duration;
            key.position.set(-3, 4, 5);
            positionRims();
        }
        draw();
        if (canRender() && !reducedMotion.matches) frame = requestAnimationFrame(tick);
    }

    function resetSpin() {
        Object.assign(spin, { angle: 0, from: 0, to: 0, elapsed: SPIN_DURATION, velocity: 0, landing: null });
    }

    function resetBurst() {
        Object.assign(burst, { phase: null, elapsed: 0, pitch: 0, yaw: 0, roll: 0, x: 0, y: 0, from: null, to: null });
    }

    function updateBurst(dt) {
        if (!burst.phase) return;
        burst.elapsed += dt;
        if (burst.phase === 'winding') {
            // Take over while the nod is still moving down, carrying its
            // velocity straight into the accelerating forward somersault.
            const nodProgress = Math.min(burst.elapsed, BURST_NOD_LEAD) / SECRET_NOD_DURATION;
            const nod = Math.sin(Math.PI * nodProgress) ** 2 * (0.025 + 3 * 0.015);
            const spinDuration = BURST_WINDUP_DURATION - BURST_NOD_LEAD;
            const t = Math.max(0, Math.min((burst.elapsed - BURST_NOD_LEAD) / spinDuration, 1));
            const nodVelocity = (0.025 + 3 * 0.015) * Math.PI / SECRET_NOD_DURATION
                * Math.sin(2 * Math.PI * BURST_NOD_LEAD / SECRET_NOD_DURATION);
            const spinTime = Math.max(0, burst.elapsed - BURST_NOD_LEAD);
            const exponent = 1.8;
            const exponential = (Math.exp(exponent * t) - 1 - exponent * t)
                / (Math.exp(exponent) - 1 - exponent);
            // If lazy flock initialization takes longer, keep the momentum.
            const coast = Math.max(0, burst.elapsed - BURST_WINDUP_DURATION)
                * exponent * (Math.exp(exponent) - 1)
                / ((Math.exp(exponent) - 1 - exponent) * spinDuration);
            const turns = (exponential + coast) * Math.PI * 2 * 1.6;
            burst.pitch = nod + nodVelocity * spinTime + turns;
            burst.yaw = turns * 0.42;
            burst.roll = -turns * 0.6;
            burst.x = -0.04 * Math.sin(t * Math.PI / 2);
            burst.y = 0.05 * Math.sin(t * Math.PI / 2);
        } else {
            const t = Math.min(burst.elapsed / BURST_SETTLE_DURATION, 1);
            const ease = 1 - (1 - t) ** 3;
            for (const axis of ['pitch', 'yaw', 'roll', 'x', 'y']) {
                burst[axis] = burst.from[axis] + (burst.to[axis] - burst.from[axis]) * ease;
            }
            // Whole turns meet the flying pose without snapping backwards.
            if (t === 1) resetBurst();
        }
    }

    function releaseBurst() {
        if (burst.phase !== 'winding') return;
        burst.from = { pitch: burst.pitch, yaw: burst.yaw, roll: burst.roll, x: burst.x, y: burst.y };
        burst.to = { x: 0, y: 0 };
        for (const axis of ['pitch', 'yaw', 'roll']) {
            const angle = burst[axis];
            burst.to[axis] = Math.sign(angle) * Math.ceil(Math.abs(angle) / (Math.PI * 2)) * Math.PI * 2;
        }
        burst.phase = 'released';
        burst.elapsed = 0;
    }

    // setupNavigation runs first, so aria-expanded reflects this click's result.
    stage.addEventListener('click', () => {
        if (stage.getAttribute('aria-expanded') !== 'true' || reducedMotion.matches || burst.phase) return;
        spin.from = spin.angle;
        spin.to += Math.PI * 2;
        spin.elapsed = 0;
        spin.landing = null;
        attention.glance = 0;
    });

    function resize() {
        width = stage.clientWidth;
        height = stage.clientHeight;
        if (!width || !height) { sync(); return; }
        camera.aspect = width / height;
        const tanHalf = Math.tan(camera.fov * Math.PI / 360);
        const fit = Math.max(halfHeight, halfWidth / camera.aspect) / tanHalf + halfDepth;
        const cap = size.x * height / (2 * MAX_WIDTH * tanHalf) + halfDepth;
        camera.position.set(0, 0, Math.max(fit, cap));
        camera.updateProjectionMatrix();
        sync();
    }

    function trackPointer(event) {
        if (event.pointerType !== 'mouse' && !event.buttons) return;
        pointer.x = event.clientX;
        pointer.y = event.clientY;
        pointer.active = true;
        pointer.movedAt = performance.now();
    }
    function updateAttention() {
        if (reducedMotion.matches) sync();
    }
    document.body.addEventListener('easterEggProgress', event => {
        discovery.count = Math.max(0, Math.min(3, event.detail.count));
        discovery.nodElapsed = discovery.count ? 0 : SECRET_NOD_DURATION;
        if (discovery.count === 3 && !reducedMotion.matches) {
            resetSpin();
            resetBurst();
            burst.phase = 'winding';
        } else if (!discovery.count) resetBurst();
        updateAttention();
    });
    let touchLink = null;
    for (const link of nav.querySelectorAll('a')) {
        link.addEventListener('pointerenter', event => {
            if (event.pointerType === 'touch') return;
            attention.link = link;
            updateAttention();
        });
        link.addEventListener('pointerleave', event => {
            // Hand off immediately, including when reduced motion draws here.
            const next = event.relatedTarget?.closest?.('#site-nav a');
            if (attention.link === link) attention.link = next || null;
            updateAttention();
        });
        link.addEventListener('focus', () => { attention.focusedLink = link; updateAttention(); });
        link.addEventListener('blur', () => { attention.focusedLink = null; updateAttention(); });
        link.addEventListener('click', event => {
            // Older browsers expose touch clicks as MouseEvents. Remember the
            // pressed link as well, and keep watching it while navigation loads.
            if (event.pointerType !== 'touch' && touchLink !== link) return;
            attention.selectedLink = link;
            touchLink = null;
            updateAttention();
        });
    }
    egg?.addEventListener('pointerenter', event => {
        if (event.pointerType === 'touch') return;
        attention.egg = true;
        updateAttention();
    });
    egg?.addEventListener('pointerleave', () => { attention.egg = false; updateAttention(); });
    function clearAttention() {
        attention.link = null;
        attention.pressedLink = null;
        attention.focusedLink = null;
        attention.egg = false;
        updateAttention();
    }
    stage.addEventListener('pointerenter', event => { hovered = event.pointerType === 'mouse'; });
    stage.addEventListener('pointerleave', () => { hovered = false; });
    window.addEventListener('pointermove', trackPointer, { passive: true });
    window.addEventListener('pointerdown', event => {
        touchLink = event.pointerType === 'touch' ? event.target.closest?.('#site-nav a') : null;
        attention.selectedLink = null;
        attention.pressedLink = touchLink;
        trackPointer(event);
        updateAttention();
    }, { passive: true });
    for (const type of ['pointerup', 'pointercancel']) {
        window.addEventListener(type, event => {
            if (event.pointerType !== 'mouse') {
                pointer.active = false;
                attention.pressedLink = null;
                if (event.type === 'pointercancel') touchLink = null;
                updateAttention();
            }
        });
    }
    document.addEventListener('pointerout', event => {
        if (!event.relatedTarget) { pointer.active = false; clearAttention(); }
    });
    window.addEventListener('blur', () => { pointer.active = false; clearAttention(); });
    reducedMotion.addEventListener('change', sync);
    document.addEventListener('visibilitychange', sync);
    window.addEventListener('pageshow', () => {
        attention.selectedLink = null;
        touchLink = null;
        pointer.active = false;
        clearAttention();
        sync();
    });
    document.body.addEventListener('layoutChanged', () => {
        if (!nav.classList.contains('is-open')) {
            attention.selectedLink = null;
            clearAttention();
        }
    });
    document.body.addEventListener('scroll', () => { if (reducedMotion.matches) draw(); }, { passive: true });
    window.addEventListener('pagehide', () => cancelAnimationFrame(frame));
    new ResizeObserver(resize).observe(stage);
    window.addEventListener('resize', resize);
    new IntersectionObserver(([entry]) => {
        inView = entry.isIntersecting;
        if (!inView) heroField.available = false;
        sync();
    }).observe(stage);

    function setFlight(active, duration = 1.8) {
        flockActive = active;
        if (active) releaseBurst();
        else {
            discovery.count = 0;
            discovery.nodElapsed = SECRET_NOD_DURATION;
            resetBurst();
        }
        heroField.active = active;
        flight.from = flight.amount;
        flight.to = active ? 1 : 0;
        flight.elapsed = 0;
        flight.duration = duration;
        if (active && flight.amount === 0) flight.phase = 0;
        resetSpin();
        stage.classList.toggle('pig-flocking', active);
        stage.disabled = active || contextLost || !stage.classList.contains('pig-ready');
        sync();
    }
    document.body.addEventListener('simulationStarted', () => setFlight(true));
    document.body.addEventListener('exitAnimationStarted', () => {
        setFlight(false, END_ANIMATION_DURATION / 1000);
        // Keep the button inert until the returning flock has been cleaned up.
        stage.disabled = true;
    });
    document.body.addEventListener('simulationStopped', () => setFlight(false, 0.35));
    canvas.addEventListener('webglcontextlost', () => {
        contextLost = true;
        heroField.available = false;
        stage.disabled = true;
        stage.classList.remove('pig-ready');
        sync();
    });
    canvas.addEventListener('webglcontextrestored', () => {
        contextLost = false;
        resize();
    });
    if (flockActive) setFlight(true);
    resize();
}

const stage = document.getElementById('pigStage');
if (stage) {
    const showFallbackNavigation = setupNavigation(stage);
    mountPig(stage).catch(error => {
        console.warn('3D pig unavailable.', error);
        showFallbackNavigation();
    });
}
